#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maximalNetworkRank(int n, vector<vector<int>>& roads) {
        vector<int> deg(n, 0);
        vector<vector<bool>> connected(n, vector<bool>(n, false));
        for (const auto& r : roads) {
            deg[r[0]]++;
            deg[r[1]]++;
            connected[r[0]][r[1]] = true;
            connected[r[1]][r[0]] = true;
        }
        int max_rank = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int rank = deg[i] + deg[j] - (connected[i][j] ? 1 : 0);
                max_rank = max(max_rank, rank);
            }
        }
        return max_rank;
    }
};

class Solution {
    public int maximalNetworkRank(int n, int[][] roads) {
        int[] deg = new int[n];
        boolean[][] connected = new boolean[n][n];
        for (int[] r : roads) {
            deg[r[0]]++;
            deg[r[1]]++;
            connected[r[0]][r[1]] = true;
            connected[r[1]][r[0]] = true;
        }
        int maxRank = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int rank = deg[i] + deg[j] - (connected[i][j] ? 1 : 0);
                maxRank = Math.max(maxRank, rank);
            }
        }
        return maxRank;
    }
}

/**
 * @param {number} n
 * @param {number[][]} roads
 * @return {number}
